# Verify orientation against evaluated_agent_role, rather than sentence order.
for number in (5, 8, 13, 17, 19, 29, 34):
    shared, policy_fact, environment_fact, history = VIEWS[number]
    VIEWS[number] = (shared, environment_fact, policy_fact, history)

def prepare():
    old = BASE / 'observed_evidence_v6_pilot_preparation'
    cases=[]
    for number in range(1,51):
        source=ROOT / f'data/gpt50/experiment/scenario/scenarios_state_v3/scenario_{number:03d}/scenario_{number:03d}.json'
        original=load(source)
        if number in (2,3,26):
            scenario=load(old / f'scenarios/gpt_{number:03d}.json')
            reused=True
        else:
            shared,pprivate,eprivate,history=VIEWS[number]
            scenario=deepcopy(original)
            scenario.update(shared_background=shared,policy_background=shared+' '+pprivate,
                            environment_background=shared+' '+eprivate)
            grants=[policy_narrative_reference(scenario,f'relevant_history.{i}') for i in history]
            scenario['policy_visible_narrative']=grants
            scenario['environment_visible_narrative']=deepcopy(grants)
            reused=False
        visibility={'policy_background','environment_background','shared_background','policy_visible_narrative','environment_visible_narrative'}
        assert {k:v for k,v in scenario.items() if k not in visibility}==original, 'Source/state changed'
        validate_scenario(scenario)
        observation=build_initial_policy_observation(scenario)
        assert observation['background']==scenario['policy_background']
        candidate=OUT / f'scenarios/gpt_{number:03d}.json'
        if candidate.exists():
            assert load(candidate)==scenario, 'Prepared input changed'
        else: save(candidate,scenario)
        cases.append({'scenario_id':scenario['scenario_id'],'policy':'gpt', 'source':str(source.relative_to(ROOT)),
                      'source_sha256':sha(source),'candidate':str(candidate.relative_to(ROOT)),
                      'candidate_sha256':sha(candidate),'reused_prior_visibility':reused,
                      'visibility_review':'agent_curated_pending_formal_human_review',
                      'author_background_and_state_unchanged':True})
    manifest={'cases':cases,'count':50,'formal_admission':False,'user_authorization':'那就扩大吧，咱们gpt不是本来就是50个场景吗，'}
    path=OUT/'manifest.json'
    if path.exists(): assert load(path)==manifest
    else: save(path,manifest)
    lines=['GPT50：双方可见背景审核入口（助手整理；待正式人工审核）','原始背景、初始 state 与标签均未修改。未来结果未授权给任一角色。','']
    for c in cases:
        s=load(ROOT/c['candidate'])
        lines += [c['scenario_id'], '共同背景：'+s['shared_background'], 'policy：'+s['policy_background'],
                  'environment：'+s['environment_background'], 'policy 历史授权：'+str(s['policy_visible_narrative']),
                  'environment 历史授权：'+str(s['environment_visible_narrative']), '']
    (OUT/'visibility_review.txt').write_text('\n'.join(lines)+'\n')
    return manifest

if __name__=='__main__':
    print('Prepared',prepare()['count'],'role-visible GPT scenarios; zero model calls.')
